        execSync('git add test.txt', { stdio: 'pipe' });
        execSync('git commit -m "feat: add new feature"', { stdio: 'pipe' });

        // Create fix commit
        fs.writeFileSync(path.join(tempDir, 'test.txt'), 'content3');
